<script setup lang="ts">
import {ref,watch} from 'vue'
import AnnualWagePanel from './AnnualWagePanel.vue'
import WageEventReview from './WageEventReview.vue'
import {usePayrollPage} from '../payrollPage'
import {changeField,changeValue,changeWarning} from '../payChangeDisplay'
import {supplementalSourceName} from '../supplemental'
import {changeState} from '../payChanges'
import type {PayChange,PayChangeImpact} from '../payChanges'
const props=defineProps<{request:PayChange;headOffice:boolean;busy:boolean;readOnly?:boolean}>(),emit=defineEmits<{action:[verb:string,note:string];edit:[]}>(),{english,api,message,current,issue}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
let previewRevision=0
const note=ref(''),month=ref(''),impact=ref<PayChangeImpact|null>(null),error=ref(''),estimating=ref(false)
watch(()=>props.request,r=>{previewRevision++;estimating.value=false;note.value='';month.value=r.content.months[0]?.month||r.effectiveDate.slice(0,7);impact.value=null;error.value=''},{immediate:true})
watch(month,()=>{previewRevision++;impact.value=null;error.value='';estimating.value=false})
function invalidateImpact(){previewRevision++;impact.value=null;estimating.value=false;error.value=''}
async function preview(){
 const r=props.request,selectedMonth=month.value,rev=++previewRevision
 impact.value=null;estimating.value=true;error.value=''
 try{
  const v=await api().get<PayChangeImpact>(`/pay-change-requests/${r.id}/impact?month=${selectedMonth}`)
  if(!current()||rev!==previewRevision)return
  if(v.requestId!==r.id||v.revision!==r.revision||v.hash!==r.hash||v.month!==selectedMonth){error.value=x('预览已过期，请重新读取申请并预估。','Preview is stale; reload the request and estimate again.');return}
  impact.value=v
 }catch(e){if(current()&&rev===previewRevision)error.value=message(e)}finally{if(current()&&rev===previewRevision)estimating.value=false}
}
</script>
<template><article class="wf-section"><h3>{{request.content.profile?.employeeName||request.content.beforeProfile?.employeeName||request.content.adoption?.name||request.employeeId}}</h3><p>{{x('审批状态','Approval state')}}: {{changeState(request.status,english())}} · {{x('修订','Revision')}} {{request.revision}} · {{request.effectiveDate}}</p><p>{{request.content.reason}}</p><p>{{x('生效状态','Effectivity')}}: {{request.effectivity==='future'?x('批准待生效','Approved, future effective date'):request.effectivity==='effective'?x('按日期生效','Effective by date'):request.effectivity==='history'?x('历史有效版本','Historical effective version'):x('尚未生效','Not effective')}}</p><p v-if="request.content.beforeProfile" class="wf-hint">{{x('原方案／模板版本','Original profile / template version')}}: {{request.content.beforeProfile.version}} / {{request.content.beforeProfile.templateVersion}}</p><p v-if="!request.adoptionId" class="wf-hint">{{request.status==='approved'?(request.effectivity==='future'?x('批准待生效','Approved, future effective date'):x('已批准有效版本；工资按有效日期解析','Approved version; payroll resolves effective dates')):x('尚未计入工资；继续使用原有效方案，没有方案则阻断计算。','Not included in payroll; the effective plan remains in use. Missing plans block calculation.')}}</p><p v-if="request.adoptionId" class="wf-hint">{{x('门店派生只生成新候选，不自动修改员工方案。','Store derivation creates a candidate; employee profiles remain unchanged.')}} {{x('母版/版本','Master / version')}}: {{request.content.adoption?.masterId}} / {{request.content.adoption?.releaseVersion}} · {{x('本店采用版本','Store adoption version')}} {{request.content.adoption?.storeVersion}} · {{x('采用状态','Adoption state')}}: {{request.status==='approved'?x('已批准本店候选，按生效日期解析','Approved store candidate; resolved by effective date'):x('原采用保持固定，变更尚未计入','Current adoption fixed; change not applied')}}</p><p v-else>{{x('影响员工','Affected employee')}}: {{request.employeeId}} · {{request.content.months.map(m=>m.month).join(', ')}}</p><p v-if="request.staleReason" role="alert">{{request.staleReason}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{x('修改项','Field')}}</th><th>{{x('变更前','Before')}}</th><th>{{x('变更后','After')}}</th></tr></thead><tbody><tr v-for="d in request.content.patch" :key="d.path"><td>{{changeField(d.path,english())}}</td><td class="pay-change-value">{{changeValue(d.before,english())}}</td><td class="pay-change-value">{{changeValue(d.after,english())}}</td></tr></tbody></table></div><section v-for="m in request.content.months.filter(m=>[...m.before.items,...m.after.items].some(i=>i.kind==='wage_event'))" :key="m.month" class="wf-section"><h3>{{m.month}} · {{x('工资事项变更前／后','Wage events before / after')}}</h3><h4>{{x('变更前（原有效凭证）','Before (original effective evidence)')}}</h4><WageEventReview :items="m.before.items" :month="m.month"/><p v-if="!m.before.items.some(i=>i.kind==='wage_event')">{{x('无原工资事项','No previous wage event')}}</p><h4>{{x('变更后（本次申请凭证）','After (proposed evidence)')}}</h4><WageEventReview :items="m.after.items" :month="m.month"/><p v-if="!m.after.items.some(i=>i.kind==='wage_event')">{{x('本次申请移除工资事项','Wage events removed by this request')}}</p></section><section v-for="proposal in request.content.supplemental||[]" :key="proposal.id" class="wf-section"><h3>{{x('独立补发方案','Supplemental proposal')}} · {{proposal.originMonth}} → {{proposal.settlementMonth}}</h3><p>{{x('原来源（只读）','Original source (read only)')}}: {{supplementalSourceName(proposal.source.kind,english())}} · {{proposal.source.batchId||proposal.source.openingVersion||'—'}} · {{proposal.source.snapshotHash}}</p><p>{{proposal.evidenceReference}}</p><WageEventReview :items="proposal.items" :month="proposal.originMonth"/></section><p v-if="request.content.supplemental?.length" class="wf-hint">{{x('补发新收入逐项列示；补发净额在独立批次计算前未知。年度来源变化后须重新核对；普通月预估不代表补发净额。','New supplemental gross is shown item by item. Supplemental net is unknown until the independent batch is calculated. Review changed annual sources; ordinary monthly estimates do not represent supplemental net.')}}</p><div v-if="!request.adoptionId&&!request.content.supplemental?.length" class="wf-toolbar"><label>{{x('预估月份','Estimate month')}}<input v-model="month" type="month" :disabled="busy" :aria-label="x('预估月份','Estimate month')"></label><button :disabled="busy||estimating" @click="preview">{{x('影响预估','Estimate impact')}}</button></div><p v-if="error" role="alert">{{error}}</p><section v-if="impact"><p class="wf-hint">{{x('只读预估；实际净额取决于本月来源、考勤及法定扣缴，未知金额不代表零。','Read-only estimate using monthly sources, attendance and statutory contributions. Unknown amounts are not zero.')}}</p><p>{{x('标准差额（确定）','Standard difference (exact)')}}: {{impact.standardDifference??x('未知','Unknown')}} · {{x('预估净额前/后/差额','Estimated net before / after / delta')}}: {{impact.beforeNet??x('未知','Unknown')}} / {{impact.afterNet??x('未知','Unknown')}} / {{impact.netDifference??x('未知','Unknown')}}</p><p>{{impact.issues.map(code=>issue(code)+' ('+code+')').join(' · ')}} {{impact.warnings.map(code=>changeWarning(code,english())).join(' · ')}}</p><small>{{impact.capturedAt}} · {{impact.beforeFingerprint}} → {{impact.afterFingerprint}}</small></section><div v-if="!readOnly" class="wf-form-actions"><button v-if="['draft','withdrawn'].includes(request.status)" :disabled="busy" @click="emit('edit')">{{x('编辑草稿','Edit draft')}}</button><button v-if="['draft','withdrawn'].includes(request.status)" :disabled="busy" @click="emit('action','submit','')">{{x('提交审批','Submit')}}</button><button v-if="request.status==='submitted'" :disabled="busy" @click="emit('action','withdraw','')">{{x('撤回','Withdraw')}}</button></div><section v-if="!readOnly&&headOffice&&request.status==='submitted'"><label>{{x('审批说明','Decision note')}}<textarea v-model="note" :aria-label="x('审批说明','Decision note')" maxlength="1000"/></label><button :disabled="busy||!note.trim()" @click="emit('action','approve',note.trim())">{{x('批准','Approve')}}</button><button :disabled="busy||!note.trim()" @click="emit('action','reject',note.trim())">{{x('驳回','Reject')}}</button></section><AnnualWagePanel v-if="request.employeeId&&!request.adoptionId" :company-id="request.companyId" :employee-id="request.employeeId" :year="Number(month.slice(0,4))" :source-version="request.revision" @changed="invalidateImpact"/><details><summary>{{x('操作记录与版本证据','History and version evidence')}}</summary><p>{{request.id}} · {{request.hash}}</p><p v-for="(event,i) in request.events" :key="i">{{event.action}} · {{event.revision}} · {{event.at}} · {{event.note}}</p></details></article></template>
<style scoped>.pay-change-value{max-width:28rem;white-space:pre-wrap;overflow-wrap:anywhere}small{overflow-wrap:anywhere}</style>
